//! Compare registry→factory scripted composition with retained native rows.
use spore_core::{cell_provider_registry_factory_join_v1::{project,Route},cell_provider_factory_validate_v1::Action};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let p=std::env::args().nth(1).expect("native stdout");let b=std::fs::read(p).unwrap();assert_eq!(b.len(),320);for i in 0..8{let k=i%4;let cw=if i>=4{0x37f}else{0x27f};let route=match k{0=>Route::Hit,1=>Route::Miss{candidate:None,validator_result:None},2=>Route::Miss{candidate:Some(3),validator_result:Some(Some(1))},_=>Route::Miss{candidate:Some(3),validator_result:Some(None)}};let x=project(route,Some(2),0x12345678,cw,0x1f80,true).unwrap();let r=&b[i*40..(i+1)*40];assert_eq!(w(r,0),x.slot.unwrap_or(0));assert_eq!(w(r,4),1);let miss=u32::from(k!=0);assert_eq!(w(r,8),miss);assert_eq!(w(r,12),miss);assert_eq!(w(r,16),1-miss);assert_eq!(w(r,20),u32::from(k>=2));assert_eq!(w(r,24),if x.factory_actions.contains(&Action::ReleaseSecond(3)){3}else{0});let fp=w(r,28);assert_eq!(fp&0xffff,cw as u32);assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(r,32)&!0x3f,0x1f80);assert_eq!(w(r,36),i as u32);}println!("matched 8 retained registry/factory rows; callbacks scripted");}
